import pandas as pd, numpy as np
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv']
D={f:pd.read_csv(f).iloc[::5].reset_index(drop=True) for f in files}
def sim(p,d):
    Kq,Tq,Kp,Tp,Tw,Tv,Kd=p
    t=d.time_s.values; V=d.voltage_pu.values; th=d.bus_angle_rad.values; Vs=d.voltage_setpoint_pu.values
    dt=t[1]-t[0]; Qb=d.reactive_power_pu.values[0]; Pb=d.active_power_pu.values[0]; V0=V[0]
    P=np.zeros(len(t));Q=np.zeros(len(t))
    xq=Qb; xp=Pb; z=th[0]; vf=V0
    for i in range(len(t)):
        Q[i]=xq; P[i]=xp
        om=(th[i]-z)/Tw
        xq+=dt*(Qb+Kq*(Vs[i]-vf)-xq)/Tq
        xp+=dt*(Pb-Kp*om-xp)/Tp
        z+=dt*(th[i]-z)/Tw
        vf+=dt*(V[i]-vf)/Tv
    return P,Q
def resid(p,fs,which):
    r=[]
    for f in fs:
        d=D[f]; P,Q=sim(p,d)
        if 'P' in which: r.append(P-d.active_power_pu.values)
        if 'Q' in which: r.append(Q-d.reactive_power_pu.values)
    return np.concatenate(r)
p0=[25,3.5,0.0447,0.016,0.006,0.02,0]
res=least_squares(resid,p0,args=(files[:2],'Q'),bounds=([0,0.05,0,1e-3,1e-4,1e-3,0],[200,20,50,50,50,5,0.0001]))
print(res.x,np.sqrt(np.mean(res.fun**2)))
for f in files: print(f, np.sqrt(np.mean(resid(res.x,[f],'Q')**2)))
